<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {state,init,attempt,undo,replace,shared,putShared,sendMidi,flushEdits} from './store'
import {sources,targets,newRoute,defaultMpeRoutes,drumParts,partName,clone,factory,type Route} from './model'
import {request,native} from './native/bridge'
import {drag} from './drag'
import {themeId} from './theme/current'
import {THEMES,THEME_GROUPS,themeGroup,themeById} from './theme/themes'
import {midiNoteName} from './lib/format'
import Seaboard from './components/Seaboard.vue'
import MidiImport from './components/MidiImport.vue'
import SoundPanel from './components/SoundPanel.vue'
import ZoneEditor from './components/ZoneEditor.vue'
import AssetBrowser from './components/AssetBrowser.vue'
const selected=computed(()=>state.patch.keys.find(k=>k.note===state.selected))
const base=ref(36),advancedPart=ref(false)
watch(()=>state.selected,()=>{advancedPart.value=false})
watch(()=>shared['ui/theme']?.revision,()=>{const value=shared['ui/theme']?.value;if(value)themeId.value=themeById(String(value)).id},{immediate:true})
function setTheme(e:Event){themeId.value=(e.target as HTMLSelectElement).value;void attempt(()=>putShared('ui/theme',themeId.value))}
function setPart(e:Event){if(!selected.value)return;const part=drumParts.find(p=>p.name===(e.target as HTMLSelectElement).value);if(part)selected.value.parts=[...part.notes];else advancedPart.value=true}
function autoMap(){if(selected.value){selected.value.routes=defaultMpeRoutes();selected.value.mpeDefaultsVersion=1}}

const patches=computed(()=>Object.values(shared).filter(f=>f.key.startsWith('patch/')&&f.value))
const grids=[{name:'Immediate',value:0},{name:'1/32',value:.125},{name:'1/16',value:.25},{name:'1/8',value:.5},{name:'1/4',value:1},{name:'Bar',value:4}]
function panic(){sendMidi([0xb0,123,0]);attempt(()=>request('stopPreview'))}
function output(e:Event){const value=Number((e.target as HTMLInputElement).value);state.telemetry.output=value;if(native())void attempt(()=>request('parameter',{id:'volume',value}))}
function addRoute(source=3,target='volume'){if(!selected.value)return;if(selected.value.routes.length+state.patch.globalRoutes.length>=16){state.error='Each key supports 16 mappings, including global controllers. Remove a mapping before adding another.';return}selected.value.routes.push(newRoute(source,target))}
function bind(target:string){if(state.bindSource<0||!selected.value)return;if(!targets.some(t=>t[0]===target)){state.error='This control is edited in the sound panel; choose a supported expression destination.';return}addRoute(state.bindSource,target);state.bindSource=-1}
function retarget(route:Route){const defaults=newRoute(route.source,route.target);route.min=defaults.min;route.max=defaults.max}
async function savePatch(){await flushEdits();if(!await putShared(`patch/${state.patch.name}`,clone(state.patch)))throw Error('Another instance saved this patch first. Rename your patch or review the saved version before saving again.');state.status=`Saved “${state.patch.name}”`}
async function exportPatch(){await flushEdits();await request('savePatch',clone(state.patch))}
async function openPatch(){const p=await request('openPatch');if(p)await replace(p)}
function keydown(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey)}}
onMounted(()=>{void attempt(init);window.addEventListener('keydown',keydown)});onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown)})
</script>
<template><v-app><div class="instrument">
<header class="masthead"><div class="brand"><span class="brand-mark">≋</span><div>ROLI DRUMMER<small>EXPRESSIVE PATTERN INSTRUMENT</small></div></div><div class="patch-title"><input v-model="state.patch.name" aria-label="Patch name"/><span>{{state.saving?'Updating…':'●'}}</span></div><div class="transport"><button v-if="state.standalone" @click="attempt(()=>request('transport',!state.telemetry.playing))">{{state.telemetry.playing?'■ Stop':'▶ Play'}}</button><span :class="{lit:state.telemetry.playing||state.telemetry.freePlaying}">●</span><b>{{state.telemetry.bpm.toFixed(1)}}</b><small>BPM · {{state.telemetry.freePlaying?'KEYS':state.standalone?'INTERNAL':'HOST'}}</small><span class="position">{{Math.floor(state.telemetry.ppq/4)+1}} : {{(state.telemetry.ppq%4+1).toFixed(1)}}</span><div class="meter"><i :style="{width:`${Math.min(1,state.telemetry.peak)*100}%`}"/></div><label class="output-control">Output<input type="range" min="0" max="1.5" step=".001" :value="state.telemetry.output" aria-label="Output gain" @input="output"/></label><button @click="panic">Panic</button></div></header>
<nav class="tabs"><button v-for="tab in ['Key','Sounds','Patterns','Patches']" :key="tab" :class="{active:state.tab===tab}" @click="state.tab=tab">{{tab}}</button><span class="tab-spacer"/><select class="theme-picker" aria-label="Color theme" :value="themeId" @change="setTheme"><optgroup v-for="group in THEME_GROUPS" :key="group" :label="group"><option v-for="theme in THEMES.filter(t=>themeGroup(t)===group)" :key="theme.id" :value="theme.id">{{theme.name}}</option></optgroup></select><button :disabled="!state.history.length" @click="undo()">↶ Undo</button><button :disabled="!state.future.length" @click="undo(true)">↷ Redo</button></nav>
<section class="upper">
<div v-if="state.tab==='Key'&&selected" class="key-editor"><div class="selected-title"><div class="key-identity"><span class="eyebrow">SELECTED KEY · {{midiNoteName(selected.note)}}</span><input v-model="selected.name" aria-label="Key name"/></div><label>Drum part<select :value="partName(selected.parts)" @change="setPart"><option v-for="part in drumParts" :key="part.name" :value="part.name">{{part.name}}</option><option value="Custom">Custom…</option></select></label><button class="part-details" @click="advancedPart=!advancedPart">{{advancedPart?'Hide details':'Edit note filter…'}}</button><label>Playback<select v-model="selected.sound.s.mode"><option value="stack">One shot</option><option value="hold">Follow note duration</option></select></label></div><div v-if="advancedPart" class="part-explanation"><label>MIDI drum notes<input :value="selected.parts.join(', ')" aria-label="MIDI drum note filter" @change="selected.parts=($event.target as HTMLInputElement).value.split(',').map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<=127)"/></label><span>Play only this drum part from the chosen pattern. These are the drum notes inside the MIDI file, not the Seaboard key you hold.</span></div><div class="key-editor-body"><SoundPanel :sound="selected.sound" :note="selected.note" @bind="bind"/><aside class="key-bindings"><div class="section-label">EXPRESSION <button @click="autoMap" title="Map all five MPE surfaces to useful sound controls">Auto map</button><button @click="addRoute()">＋</button></div><div class="route" v-for="(route,i) in selected.routes" :key="i"><select v-model.number="route.source" aria-label="Expression source"><option v-for="(source,index) in sources" :key="index" :value="index">{{source}}</option></select><select v-model="route.target" aria-label="Sound parameter" @change="retarget(route)"><option v-for="target in targets" :key="target[0]" :value="target[0]">{{target[0]}}</option></select><button title="Remove mapping" @click="selected.routes.splice(i,1)">×</button><div class="route-range"><label>From<input v-model.number="route.min" type="number"/></label><label>To<input v-model.number="route.max" type="number"/></label><label>Curve<input v-model.number="route.curve" type="number" min=".1" max="10" step=".1"/></label></div></div><div class="bind-row"><select v-model.number="state.bindSource" aria-label="Bind expression"><option :value="-1">Bind a surface…</option><option v-for="(source,i) in sources" :key="i" :value="i">{{source}}</option></select><span>{{state.bindSource>=0?'Click a sound knob':'Choose a surface, then a knob'}}</span></div><div class="section-label">KEY ZONES<select v-model.number="selected.zoneSource" aria-label="Zone control source"><option v-for="(source,i) in sources.slice(0,4)" :key="i" :value="i">{{source}}</option></select></div><ZoneEditor :zones="selected.zones" :scope="String(selected.note)" compact/></aside></div></div>
<div v-else-if="state.tab==='Key'" class="empty">Drop a sound on this key to assign it.</div>
<AssetBrowser v-else-if="state.tab==='Sounds'||state.tab==='Patterns'" :patterns="state.tab==='Patterns'"/>
<div v-else class="patches"><div class="patch-actions"><h2>Your instruments</h2><p>A patch holds the kit, patterns, expression mappings and zone boundaries.</p><label>Name<input v-model="state.patch.name" aria-label="Saved patch name"/></label><label>Kit level<input v-model.number="state.patch.volume" type="range" min="0" max="1.5" step=".001"/></label><button class="primary" @click="attempt(savePatch)">Save patch</button><button @click="attempt(openPatch)">Open file…</button><button @click="attempt(exportPatch)">Export portable…</button><button @click="attempt(()=>replace(factory()))">Factory kit</button><label>Launch<select v-model.number="state.patch.launchGrid"><option v-for="g in grids" :key="g.value" :value="g.value">{{g.name}}</option></select></label><label>Zone changes<select v-model.number="state.patch.switchGrid"><option v-for="g in grids" :key="g.value" :value="g.value">{{g.name}}</option></select></label><label><input v-model="state.patch.hardRelease" type="checkbox"/> Stop voices on release</label><label v-if="state.standalone">Tempo<input v-model.number="state.patch.bpm" type="number" min="20" max="400"/></label></div><div class="patch-cards"><button v-for="patch in patches" :key="patch.key" class="patch-card" @click="attempt(()=>replace(patch.value))"><span>≋</span><b>{{patch.value.name}}</b><small>{{patch.value.keys.length}} keys · {{patch.value.clips.length}} patterns</small></button><div v-if="!patches.length" class="empty">Save your first patch to see it here.</div></div></div>
</section>
<section class="performance"><div class="performance-toolbar"><span class="section-label">SEABOARD</span><span v-if="selected">{{selected.name}} <small>· Note {{selected.note}}</small></span><span class="tab-spacer"/><label>First note<input v-model.number="base" type="number" min="0" :max="72" step="12" @change="base=Math.max(0,Math.min(72,Math.round((Number(base)||0)/12)*12))"/></label><button @click="state.patch.keys.forEach(k=>k.zones=clone(state.patch.templateZones))">Apply zones to all keys</button></div><div class="performance-body"><Seaboard :base="base"/><div class="template-zones"><ZoneEditor :zones="state.patch.templateZones" scope="template"/></div></div></section>
<footer class="status"><span>{{state.error||state.status||(state.bindSource>=0?'Click a knob to bind expression':'Hold a key to hear its part. Slide to change patterns.')}}</span><button v-if="state.error" @click="state.error=''">Dismiss</button><span class="tab-spacer"/><span class="mpe-monitor" :title="'Latest incoming slide message; per-channel values drive the finger markers'">{{state.telemetry.slideChannel>=0?`Slide ${Math.round(state.telemetry.slideValue/127*100)}% · Ch ${state.telemetry.slideChannel+1}`:'Slide: waiting for CC74'}}</span><span>{{state.telemetry.voices}} voices · {{state.telemetry.clips}} clip buses</span><span v-if="state.telemetry.overflow" class="error">Event limit reached</span><span>{{native()?'NATIVE AUDIO':'EDITOR PREVIEW'}}</span></footer>
<div v-if="drag.active" class="drag-ghost" :style="{left:`${drag.x+14}px`,top:`${drag.y+14}px`}">{{drag.asset?.name}}</div>
<MidiImport/></div></v-app></template>
